insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-property-in-dubai-on-a-visit-visa', 'Can I buy property in Dubai on a visit visa?', '<p>Yes for cash purchases with valid ID; mortgage approval typically requires residency. <a href="/pages/contact">contact our team</a> to plan your purchase timeline.</p>', 'Can I buy property in Dubai on a visit visa?', 42, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-golden-visa-property-investment-threshold', 'What is Golden Visa property investment threshold?', '<p>UAE Golden Visa property routes have minimum investment thresholds (historically around AED 2M+ for certain categories — verify current GDRFA rules). <a href="/pages/contact">contact our team</a> for latest eligibility.</p>', 'What is Golden Visa property investment threshold?', 43, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-is-agency-commission-calculated-on-sales', 'How is agency commission calculated on sales?', '<p>Typically 2% of sale price plus VAT, paid by buyer or seller per agreement. Disclosed in <a href="/account/transactions">property applications</a> payment breakdown before you commit.</p>', 'How is agency commission calculated on sales?', 44, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-at-property-handover-for-buyers', 'What happens at property handover for buyers?', '<p>Final payment, DLD transfer, and key collection. See <a href="/pages/shipping">Handover Information</a> and <a href="/pages/buying-guide">Buying Guide</a>. Status updates appear in <a href="/account">My Account</a>.</p>', 'What happens at property handover for buyers?', 45, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-auction-property-in-dubai', 'Can I buy auction property in Dubai?', '<p>Court and bank auctions follow different rules and due diligence. Our <a href="/collection/sales">properties for sale</a> focus on standard listings — <a href="/pages/contact">contact our team</a> for auction referrals.</p>', 'Can I buy auction property in Dubai?', 46, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-property-inspection-available-before-buying', 'Is property inspection available before buying?', '<p>Yes — schedule a viewing via any listing. <a href="/account/viewings">viewing requests</a> tracks appointments. For off-plan, review developer track record in <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Is property inspection available before buying?', 47, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-verify-a-property-title-is-clean', 'How do I verify a property title is clean?', '<p>Your agent runs DLD title deed checks for liens and encumbrances before contract. Part of our <a href="/pages/how-it-works">How It Works</a> workflow.</p>', 'How do I verify a property title is clean?', 48, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-start-browsing-dubai-properties-for-sale', 'Where do I start browsing Dubai properties for sale?', '<p>Visit <a href="/collection/sales">properties for sale</a>, <a href="/collection/new">new listings</a> listings, or <a href="/search">property search</a>. Create <a href="/account">My Account</a> to save favourites and apply online.</p>', 'Where do I start browsing Dubai properties for sale?', 49, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-book-a-property-viewing-online', 'How do I book a property viewing online?', '<p>Open a listing and click Book a Viewing or submit an inquiry with preferred dates. Confirmations appear in <a href="/account/viewings">viewing requests</a> and <a href="/account">My Account</a> notifications.</p>', 'How do I book a property viewing online?', 50, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-reschedule-a-viewing-in-dubai', 'Can I reschedule a viewing in Dubai?', '<p>Yes — <a href="/pages/contact">contact our team</a> your agent or reply to the notification. Updated times sync to <a href="/account/viewings">viewing requests</a>.</p>', 'Can I reschedule a viewing in Dubai?', 51, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-should-i-bring-to-a-property-viewing', 'What should I bring to a property viewing?', '<p>Emirates ID or passport, questions list, and tape measure if furnishing planning. Complete <a href="/account/profile">My Profile</a> beforehand for faster applications.</p>', 'What should I bring to a property viewing?', 52, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-a-typical-viewing-take', 'How long does a typical viewing take?', '<p>Apartments: 20–30 minutes. Villas: 45–60 minutes. Your agent allows time for building amenities inspection.</p>', 'How long does a typical viewing take?', 53, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-view-multiple-properties-in-one-day', 'Can I view multiple properties in one day?', '<p>Yes — <a href="/pages/contact">contact our team</a> to arrange a viewing route. Save targets from <a href="/search">property search</a> or <a href="/collection/all">all listings</a> first.</p>', 'Can I view multiple properties in one day?', 54, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-after-my-viewing-is-completed', 'What happens after my viewing is completed?', '<p>Declare Proceed, Not Proceed, or Need More Info in <a href="/account/transactions">property applications</a>. Your agent reviews and updates status. See <a href="/pages/how-it-works">How It Works</a>.</p>', 'What happens after my viewing is completed?', 55, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-track-my-property-application-status', 'How do I track my property application status?', '<p>Sign in to <a href="/account/transactions">property applications</a> for a step-by-step timeline: viewing → contract → payment → handover.</p>', 'How do I track my property application status?', 56, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-apply-for-a-property-without-a-viewing', 'Can I apply for a property without a viewing?', '<p>Some off-plan or remote buyers proceed with video tours; most owners prefer in-person viewings for ready units. <a href="/pages/contact">contact our team</a> for virtual options.</p>', 'Can I apply for a property without a viewing?', 57, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-many-properties-can-i-apply-for-at-once', 'How many properties can I apply for at once?', '<p>Multiple inquiries are fine, but serious applications should focus on 1–2 priorities. Each has a separate <a href="/account/transactions">property applications</a> record.</p>', 'How many properties can I apply for at once?', 58, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-property-transaction-number', 'What is a property transaction number?', '<p>A unique reference (e.g. PT-000123) for your application. Shown in <a href="/account/transactions">property applications</a> and all email notifications.</p>', 'What is a property transaction number?', 59, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-is-my-assigned-agent', 'Who is my assigned agent?', '<p>Displayed in <a href="/account/transactions">property applications</a> and viewing confirmations. <a href="/pages/about">About GW Vacation Homes</a> introduces our agent standards.</p>', 'Who is my assigned agent?', 60, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-my-spouse-join-the-application', 'Can my spouse join the application?', '<p>Yes — add co-applicant details in <a href="/account/profile">My Profile</a> and inform your agent via <a href="/pages/contact">contact our team</a>.</p>', 'Can my spouse join the application?', 61, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-fast-do-agents-respond-to-inquiries', 'How fast do agents respond to inquiries?', '<p>We aim within one business day. Urgent requests: <a href="/pages/contact">contact our team</a> or WhatsApp from any listing page.</p>', 'How fast do agents respond to inquiries?', 62, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-the-property-is-already-under-offer', 'What if the property is already under offer?', '<p>Your agent notifies you immediately and suggests similar <a href="/collection/new">new listings</a> or <a href="/search">property search</a> alternatives.</p>', 'What if the property is already under offer?', 63, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-an-account-to-book-a-viewing', 'Do I need an account to book a viewing?', '<p>An account lets you track <a href="/account/viewings">viewing requests</a> and <a href="/account/transactions">property applications</a>. Guest inquiries are possible but limit dashboard tracking — sign up via <a href="/account">My Account</a>.</p>', 'Do I need an account to book a viewing?', 64, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-cancel-a-viewing-request', 'Can I cancel a viewing request?', '<p>Yes — notify your agent before the scheduled time. Status updates in <a href="/account/viewings">viewing requests</a>.</p>', 'Can I cancel a viewing request?', 65, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-client-declaration-after-viewing', 'What is client declaration after viewing?', '<p>Your formal Proceed / Not Proceed response that unlocks contract stage if approved. Submit inside <a href="/account/transactions">property applications</a>.</p>', 'What is client declaration after viewing?', 66, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
